import hashlib

# A demonstration of a rainbow table attack.
# In a real-world scenario, the rainbow table would be pre-computed.

def make_hash(password):
    return hashlib.md5(password.encode()).hexdigest()

# Pre-computed table (Password -> Hash)
rainbow_table = {
    make_hash("123456"): "123456",
    make_hash("password"): "password",
    make_hash("pass123"): "pass123",
    make_hash("admin"): "admin",
    make_hash("letmein"): "letmein"
}

def rainbow_table_attack(hashed_passwords):
    decrypted_passwords = {}
    for g_hash in hashed_passwords:
        if g_hash in rainbow_table:
            decrypted_passwords[g_hash] = rainbow_table[g_hash]
        else:
            decrypted_passwords[g_hash] = None
    return decrypted_passwords

# Example trove of hashed passwords
trove = [
    "49f0886b9d8d28d4305d6a626a2aad2",  # hash of "123456"
    "827ccb0eea8a706c4b34a16891f84e7b",  # hash of "password"
    "a00bd25adcd29a22302d230d2c93a110"   # unknown hash
]

results = rainbow_table_attack(trove)
for hash_val, pass in results.items():
    print(f"Hash: {hash_val} -> Password: {pass}")
